WITH chosen AS (
 SELECT pa.player_api_id, pa.overall_rating, pa.defensive_work_rate,
 ROW_NUMBER() OVER (PARTITION BY pa.player_api_id ORDER BY pa.date DESC, pa.id DESC) rn
 FROM Player_Attributes pa WHERE pa.date <= '2013-07-12'
), eligible AS (
 SELECT player_api_id, overall_rating FROM chosen WHERE rn=1 AND defensive_work_rate IN ('low','medium','high')
), stats AS (
 SELECT AVG(overall_rating) avg_rating FROM eligible
), landon AS (
 SELECT e.overall_rating FROM eligible e JOIN Player p ON p.player_api_id=e.player_api_id WHERE p.player_name='Landon Donovan'
)
SELECT ROUND(100.0*(landon.overall_rating-stats.avg_rating)/stats.avg_rating,2) AS percentage_higher
FROM landon CROSS JOIN stats;

