WITH vice_president AS (
  SELECT member_id FROM member WHERE position = 'Vice President'
), latest_date AS (
  SELECT MAX(expense_date) AS expense_date
  FROM expense
  WHERE link_to_member IN (SELECT member_id FROM vice_president)
)
SELECT ld.expense_date,
       (SELECT SUM(e.cost) FROM expense e WHERE e.expense_date = ld.expense_date) AS total_cost
FROM latest_date ld;

